def process_symbol(symbol, candles):
    """Convert raw candle data to CSV."""
    rows = []
    for candle in candles:
        ts_ms = int(candle[0])
        dt = datetime.fromtimestamp(ts_ms / 1000, tz=timezone.utc)
        date_str = dt.strftime('%Y-%m-%d')
        o = float(candle[1])
        h = float(candle[2])
        l = float(candle[3])
        c = float(candle[4])
        v = float(candle[5])
        rows.append((date_str, o, h, l, c, v))

    # Sort by date ascending
    rows.sort(key=lambda x: x[0])

    # Remove duplicate dates (keep last occurrence - most recent data)
    seen = {}
    for row in rows:
        seen[row[0]] = row
    rows = sorted(seen.values(), key=lambda x: x[0])

    filepath = os.path.join(DATA_DIR, f'{symbol}.csv')
    with open(filepath, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['date', 'open', 'high', 'low', 'close', 'volume'])
        for row in rows:
            writer.writerow(row)

    print(f"  {symbol}: {len(rows)} trading days, {rows[0][0]} to {rows[-1][0]}")
    return len(rows)


if __name__ == '__main__':
    print("Saving OHLCV data to CSV files...")
    total = 0
    for symbol, data in SYMBOLS_DATA.items():
        n = process_symbol(symbol, data)
        total += n
    print(f"\nDone! {len(SYMBOLS_DATA)} symbols, {total} total records saved to {DATA_DIR}/")
